CREATE TABLE ves_rate_migration_guard (ok INTEGER NOT NULL CHECK(ok=1));
INSERT INTO ves_rate_migration_guard SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM exchange_rates WHERE currency='VES' AND deleted_at IS NULL) OR EXISTS(SELECT 1 FROM exchange_rates WHERE currency='COP' AND deleted_at IS NULL) THEN 1 ELSE 0 END;
INSERT INTO ves_rate_migration_guard SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM exchange_rates WHERE currency='VES' AND deleted_at IS NULL) OR ((SELECT CAST(rate AS REAL) FROM exchange_rates WHERE currency='COP' AND deleted_at IS NULL ORDER BY created_at DESC,id DESC LIMIT 1)/(SELECT CAST(rate AS REAL) FROM exchange_rates WHERE currency='VES' AND deleted_at IS NULL ORDER BY created_at DESC,id DESC LIMIT 1) BETWEEN 0.00000000005 AND 9999999999.999999) THEN 1 ELSE 0 END;
ALTER TABLE exchange_rates ADD COLUMN rate_base TEXT NOT NULL DEFAULT 'USD' CHECK(rate_base IN('USD','VES'));
INSERT INTO exchange_rates(id,currency,rate,created_at,created_by,rate_base) SELECT lower(hex(randomblob(16))),'VES',printf('%.10f',CAST(c.rate AS REAL)/CAST(v.rate AS REAL)),strftime('%Y-%m-%dT%H:%M:%fZ','now'),v.created_by,'VES' FROM exchange_rates v,exchange_rates c WHERE v.id=(SELECT id FROM exchange_rates WHERE currency='VES' AND deleted_at IS NULL ORDER BY created_at DESC,id DESC LIMIT 1) AND c.id=(SELECT id FROM exchange_rates WHERE currency='COP' AND deleted_at IS NULL ORDER BY created_at DESC,id DESC LIMIT 1);
DROP TABLE ves_rate_migration_guard;
DROP TRIGGER order_trash_dependencies;
CREATE TRIGGER order_trash_dependencies BEFORE INSERT ON orders WHEN EXISTS(SELECT 1 FROM clients WHERE id=new.client_id AND deleted_at IS NOT NULL) OR EXISTS(SELECT 1 FROM user WHERE id=new.author_id AND deleted_at IS NOT NULL) OR (new.cop_rate_id IS NOT NULL AND new.cop_rate_id IS NOT (SELECT id FROM exchange_rates WHERE currency='COP' AND deleted_at IS NULL ORDER BY created_at DESC,id DESC LIMIT 1)) OR (new.currency='VES' AND (new.rate_id IS NULL OR new.rate_id IS NOT (SELECT id FROM exchange_rates WHERE currency='VES' AND rate_base='VES' AND deleted_at IS NULL ORDER BY created_at DESC,id DESC LIMIT 1))) BEGIN SELECT RAISE(ABORT,'TRASHED_RECORD'); END;
CREATE TRIGGER ves_rate_unit_guard BEFORE INSERT ON exchange_rates WHEN new.currency='VES' AND new.rate_base<>'VES' BEGIN SELECT RAISE(ABORT,'RATE_UNIT_INVALID'); END;
